const validHeadChildren = ['title', 'base', 'link', 'meta', 'script', 'style'];

const voidElms = [
  'area',
  'base',
  'br',
  'col',
  'command',
  'embed',
  'hr',
  'img',
  'input',
  'keygen',
  'link',
  'meta',
  'param',
  'source',
  'track',
  'wbr',
];

const extraVoidElms = ['noscript', 'iframe'];

const blockNodeNames = [
  'address',
  'article',
  'aside',
  'blockquote',
  'details',
  'dialog',
  'dd',
  'div',
  'dl',
  'dt',
  'fieldset',
  'figcaption',
  'figure',
  'footer',
  'form',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
  'header',
  'hgroup',
  'hr',
  'li',
  'main',
  'nav',
  'ol',
  'p',
  'pre',
  'section',
  'ul',
];

const tableCompNames = ['table', 'thead', 'tbody', 'tfoot', 'tr', 'td', 'th', 'col', 'colgroup', 'caption'];

const notNestableElms = ['form', 'a'];

const pseudoStatesMap: Record<string, string> = {
  active: 'a',
  hover: 'b',
};
const pseudoStates = Object.keys(pseudoStatesMap);

const clonedDocument = document.implementation.createHTMLDocument('');

const childNodes = (node: Node): Node[] => {
  // TODO: import shadowRoot rewrite at document init
  const shadowRoot = (node as Element).shadowRoot;
  const children: Node[] = Array.from(node.childNodes || []);
  // TODO: double-check behaviour with custom shadowRoots and slot elements (thanks to execution context we shouldn't do anything)
  if (shadowRoot) {
    children.unshift(shadowRoot);
  }
  return children;
};

class Snapshotter {
  _nodeId: number;

  _document: Document;

  _docType: string;

  _insideHead: boolean;

  _insideParagraph: boolean;

  _insideMalformedSelect: boolean;

  _insideDescriptionItem: boolean;

  _insideButton: boolean;

  _insideMalformedIODescendant: boolean;

  _selectElmsMap: Map<HTMLSelectElement, Element>;

  _nestedElmsCounts: Record<string, number>;

  _activeElement: Element | null;

  _elmsInPseudoState: Record<string, Element[]>;

  constructor(doc: Document) {
    this._nodeId = 0;
    this._document = doc;
    this._docType = '';
    this._insideHead = false;
    this._insideParagraph = false;
    this._insideMalformedSelect = false;
    this._insideDescriptionItem = false;
    this._insideButton = false;
    this._insideMalformedIODescendant = false;
    this._selectElmsMap = new Map();
    this._nestedElmsCounts = {};
    notNestableElms.forEach((nodeName) => {
      this._nestedElmsCounts[nodeName] = 0;
    });
    this._activeElement = document.activeElement;
    while (this._activeElement?.shadowRoot) {
      this._activeElement = this._activeElement.shadowRoot.activeElement;
    }
    this._elmsInPseudoState = {};
    pseudoStates.forEach((pseudoState) => {
      this._elmsInPseudoState[pseudoState] = [];
    });
    this._importElmsInPseudoState(this._document);
    this._document.removeChild(this._document.documentElement);
    this._document.appendChild(this._document.importNode(document.documentElement, false));
    childNodes(document.documentElement).forEach((node) => {
      this._importNode(node, this._document.documentElement);
    });
    // Setting/removing selected attribute from options
    this._selectElmsMap.forEach((clonedElm, elm) => {
      const realOpts = elm.querySelectorAll('option');
      const clonedOpts = elm.querySelectorAll('option, un-es-replace[un-nodename="option"]');
      const optsCount = realOpts.length;
      for (let i = 0; i < optsCount; i += 1) {
        const realOpt = realOpts[i];
        const clonedOpt = clonedOpts[i];
        if (realOpt.selected) {
          clonedOpt.setAttribute('selected', 'selected');
        } else {
          clonedOpt.removeAttribute('selected');
        }
      }
    });
    // Converting wrong html children in un-es-replace comments
    const htmlChildren = childNodes(this._document.documentElement);
    htmlChildren.forEach((child) => {
      const nodeName = (child.nodeName || '').toLowerCase();
      if (nodeName && !nodeName.startsWith('#') && child !== this._document.head && child !== this._document.body) {
        const comment = this._document.createComment(
          `un-es-replace:${encodeURIComponent((child as Element).outerHTML)}`,
        );
        child.parentNode?.replaceChild(comment, child);
      }
    });
    // Converting <un-es-replace> nodes in scripts if they are a descendant of head (see #AUT-2726)
    const headChildrenToReplace = this._document.querySelectorAll('head > un-es-replace');
    for (let i = headChildrenToReplace.length - 1; i >= 0; i -= 1) {
      const child = headChildrenToReplace[i];
      const scriptElm = this._document.createElement('script');
      scriptElm.setAttribute('type', 'text/un-es-replace');
      scriptElm.innerHTML = encodeURIComponent(child.outerHTML);
      this._document.head.replaceChild(scriptElm, child);
    }
    // Converting text nodes in scripts if they are a descendant of head
    const headChildren = this._document.head ? childNodes(this._document.head) : [];
    for (let i = headChildren.length - 1; i >= 0; i -= 1) {
      const nodeName = headChildren[i].nodeName || '';
      if (nodeName === '#text' && (headChildren[i].nodeValue || '').trim() !== '') {
        const scriptElm = this._document.createElement('script');
        scriptElm.setAttribute('type', 'text/un-es-replace');
        scriptElm.innerHTML = encodeURIComponent(headChildren[i].nodeValue ?? '');
        this._document.head.replaceChild(scriptElm, headChildren[i]);
      }
    }
    const { doctype } = document;
    if (doctype?.name) {
      this._docType = `<!DOCTYPE ${doctype.name}${doctype.publicId ? ` PUBLIC "${doctype.publicId}"` : ''}${
        !doctype.publicId && doctype.systemId ? ' SYSTEM' : ''
      }${doctype.systemId ? ` "${doctype.systemId}"` : ''}>`;
    }
  }

  get html(): string {
    return this._docType + this._document.documentElement.outerHTML;
  }

  static run(): string {
    clonedDocument.open();
    clonedDocument.close();
    const snapshot = new Snapshotter(clonedDocument);
    return snapshot.html;
  }

  _importElmsInPseudoState(context: Document | ShadowRoot): void {
    pseudoStates.forEach((pseudoState) => {
      const targetElms = Array.from(context.querySelectorAll(`*:${pseudoState}`) || []);
      if (targetElms.length) {
        this._elmsInPseudoState[pseudoState] = this._elmsInPseudoState[pseudoState].concat(targetElms);
      }
    });
  }

  _importNode(node: Node, clonedParent: Node): void {
    if (!node) {
      return;
    }
    let nodeName = (node.nodeName || '').toLocaleLowerCase();
    if (!nodeName) {
      return;
    }

    const canBeProcessorOf = {
      head: !this._insideHead,
      paragraph: !this._insideParagraph,
      malformedSelect: !this._insideMalformedSelect,
      descriptionItem: !this._insideDescriptionItem,
      button: !this._insideButton,
      malformedIODescendant: !this._insideMalformedIODescendant,
    };

    let orNodeName = nodeName;
    let nodeNameAttr = null;
    let isNestedElm = false;
    let clonedElm: Node | null = null;
    if (node instanceof ShadowRoot) {
      clonedElm = this._document.createElement('un-shadow-elm');
      this._importElmsInPseudoState(node);
    } else if (node.nodeType === Node.TEXT_NODE) {
      clonedElm = this._document.createTextNode(node.nodeValue ?? '');
    } else if (node.nodeType === Node.CDATA_SECTION_NODE) {
      const xmlDoc = new DOMParser().parseFromString('<xml></xml>', 'application/xml');
      clonedElm = xmlDoc.createCDATASection(node.nodeValue ?? '');
    } else if (node.nodeType === Node.PROCESSING_INSTRUCTION_NODE) {
      const processingInstruction = node as ProcessingInstruction;
      clonedElm = this._document.createProcessingInstruction(processingInstruction.target, processingInstruction.data);
    } else if (node.nodeType === Node.COMMENT_NODE) {
      let parentNodeName = (clonedParent.nodeName || '').toLowerCase();
      if (parentNodeName === 'un-es-replace') {
        parentNodeName = (clonedParent as Element).getAttribute('un-nodename') ?? '';
      }
      if (parentNodeName === 'style') {
        return;
      }
      clonedElm = this._document.createComment(node.nodeValue ?? '');
    } else {
      let parentNodeName = (clonedParent.nodeName || '').toLowerCase();
      if (parentNodeName === 'un-es-replace') {
        parentNodeName = (clonedParent as Element).getAttribute('un-nodename') ?? '';
      }
      isNestedElm = typeof this._nestedElmsCounts[nodeName] !== 'undefined';
      if (isNestedElm) {
        this._nestedElmsCounts[nodeName] += 1;
        if (this._nestedElmsCounts[nodeName] > 1) {
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
        }
      }
      if (nodeName !== 'un-es-replace') {
        const elmQuerySelectorAll = (selectors: string): Element[] => {
          let descendants: Element[] = [];
          try {
            descendants = Array.from((node as Element).querySelectorAll(selectors));
          } catch (e) {
            descendants = [];
          }
          return descendants;
        };
        const inlineOnlyMode = this._insideParagraph || this._insideButton;
        if (
          (nodeName === 'html' && node !== document.documentElement) ||
          (nodeName === 'head' && node !== document.head) ||
          (nodeName === 'body' && node !== document.body)
        ) {
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
        } else if (nodeName === 'script' || nodeName === 'style') {
          if (node.childNodes.length > 1 || elmQuerySelectorAll('*').length > 0) {
            nodeNameAttr = nodeName;
            nodeName = 'un-es-replace';
          } else if (!(node.textContent || '').includes(`</${nodeName}>`)) {
            const tmpDiv = this._document.createElement('div');
            tmpDiv.innerHTML = node.textContent ?? '';
            if (tmpDiv.childNodes.length > 1 || tmpDiv.querySelectorAll('*').length) {
              nodeNameAttr = nodeName;
              nodeName = 'un-es-replace';
            }
          } else {
            nodeNameAttr = nodeName;
            nodeName = 'un-es-replace';
          }
        } else if (nodeName === 'image') {
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
        } else if (this._insideHead && !validHeadChildren.includes(nodeName)) {
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
        } else if (
          (extraVoidElms.includes(nodeName) || voidElms.includes(nodeName)) &&
          elmQuerySelectorAll('*').length > 0
        ) {
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
        } else if (
          this._insideMalformedSelect ||
          (nodeName === 'select' && elmQuerySelectorAll('*:not(option):not(optgroup)').length > 0)
        ) {
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
          this._insideMalformedSelect = true; // Updating status variable
        } else if (
          this._insideMalformedIODescendant ||
          (inlineOnlyMode && (blockNodeNames.includes(nodeName) || tableCompNames.includes(nodeName)))
        ) {
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
          this._insideMalformedIODescendant = true; // Updating status variable
        } else if (tableCompNames.includes(nodeName)) {
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
        } else if (nodeName === 'li' && parentNodeName !== 'ul' && parentNodeName !== 'ol') {
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
        } else if (this._insideDescriptionItem && (nodeName === 'dd' || nodeName === 'dt')) {
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
        } else if (this._insideButton && nodeName === 'button') {
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
        } else if (node instanceof HTMLTemplateElement) {
          // TODO: double-check if it's possible to use template nodeName
          nodeNameAttr = nodeName;
          nodeName = 'un-es-replace';
        }
      }

      // Updating status variables
      if (node === document.head) {
        this._insideHead = true;
      } else if (nodeName === 'p') {
        this._insideParagraph = true;
      } else if (nodeName === 'dd' || nodeName === 'dt') {
        this._insideDescriptionItem = true;
      } else if (nodeName === 'dl') {
        this._insideDescriptionItem = false;
      } else if (nodeName === 'button') {
        this._insideButton = true;
      }

      // Creating clone
      try {
        clonedElm = this._document.createElement(nodeName);
        if (nodeNameAttr) {
          orNodeName = nodeNameAttr;
        }
      } catch (e) {
        try {
          // Workaround for invalid nodeName
          const tmpElm = this._document.createElement('div');
          tmpElm.innerHTML = `<${nodeName}></${nodeName}>`;
          if (tmpElm.firstChild) {
            clonedElm = tmpElm.firstChild as Element;
          }
        } catch (e2) {
          // eslint-disable-line no-shadow
          clonedElm = null;
        }
      }

      if (clonedElm !== null && clonedElm instanceof Element) {
        if (nodeNameAttr) {
          clonedElm.setAttribute('un-nodename', orNodeName);
        }

        // Importing attributes
        const attributes = Array.from((node as Element).attributes);
        const attributesCount = attributes.length;
        for (let i = 0; i < attributesCount; i += 1) {
          const attribute = attributes[i];
          /**
           * Try-Catch is needed because sometimes attribute.name
           * could be NOT valid and to generate a DOM exception
           */
          try {
            clonedElm.setAttribute(attribute.name, attribute.value);
          } catch (e) {
            // continue
          }
        }

        if ((node instanceof HTMLMediaElement || node instanceof HTMLImageElement) && node.currentSrc) {
          clonedElm.setAttribute('un-curr-src', node.currentSrc);
        } else if (node instanceof HTMLIFrameElement && !node.getAttribute('un-framename')) {
          clonedElm.setAttribute('un-framename', '');
        } else if (node instanceof HTMLDialogElement && node.getAttribute('un-show-modal')) {
          clonedElm.removeAttribute('open');
        } else if (node instanceof HTMLInputElement) {
          if (node.type === 'radio' || node.type === 'checkbox') {
            if (node.checked) {
              clonedElm.setAttribute('checked', 'checked');
            } else {
              clonedElm.removeAttribute('checked');
            }
          } else {
            clonedElm.setAttribute('value', node.value);
          }
        } else if (node instanceof HTMLTextAreaElement) {
          clonedElm.innerHTML = node.value;
        } else if (node instanceof HTMLSelectElement) {
          this._selectElmsMap.set(node, clonedElm);
        } else if (node instanceof HTMLCanvasElement) {
          try {
            const dataUrl = node.toDataURL();
            clonedElm.setAttribute('un-data-url', dataUrl);
          } catch (e) {
            // do nothing, not possible to import per security exception
          }
        }

        if (node === this._activeElement) {
          clonedElm.setAttribute('un-active-elm', 'true');
        }

        const elmPseudoStates: string[] = [];
        pseudoStates.forEach((pseudoState) => {
          if (this._elmsInPseudoState[pseudoState].includes(node as Element)) {
            elmPseudoStates.push(pseudoStatesMap[pseudoState]);
          }
        });
        if (elmPseudoStates.length) {
          clonedElm.setAttribute('un-pseudos', elmPseudoStates.join(''));
        }
      }
    }

    if (!clonedElm) {
      return;
    }

    clonedParent.appendChild(clonedElm);

    let childrenImported = false;
    if (orNodeName === 'style') {
      const sheet = (node as HTMLStyleElement).sheet;
      if (sheet) {
        let innerHTML = '';
        Array.from(sheet.cssRules).forEach((cssRule) => {
          innerHTML += cssRule.cssText;
        });
        (clonedElm as Element).innerHTML = innerHTML;
        childrenImported = true;
      }
    }
    if (!childrenImported) {
      const children = childNodes(node);
      const childrenCount = children.length;
      for (let i = 0; i < childrenCount; i += 1) {
        const child = children[i];
        this._importNode(child, clonedElm);
      }
    }

    // Updating status variables
    if (canBeProcessorOf.head && this._insideHead) {
      this._insideHead = false;
    } else if (isNestedElm) {
      this._nestedElmsCounts[orNodeName] -= 1;
    } else if (canBeProcessorOf.malformedSelect && this._insideMalformedSelect) {
      this._insideMalformedSelect = false;
    } else if (canBeProcessorOf.malformedIODescendant && this._insideMalformedIODescendant) {
      this._insideMalformedIODescendant = false;
    } else if (canBeProcessorOf.paragraph && this._insideParagraph) {
      this._insideParagraph = false;
    } else if (canBeProcessorOf.descriptionItem && this._insideDescriptionItem) {
      this._insideDescriptionItem = false;
    } else if (canBeProcessorOf.button && this._insideButton) {
      this._insideButton = false;
    }
  }
}

window._AQAExt_ = { Snapshotter };

export {};
